<?php
namespace App\Controllers;
use App\Core\{Authorization,CSRF,Database,TenantContext,View,Audit,HttpException,Auth};
use App\Services\ModuleService;
final class LoyaltyController
{
    private function enabled():void{ModuleService::require('loyalty');}
    public function index():void{$this->enabled();Authorization::require('loyalty.view');$t=TenantContext::id();$pdo=Database::connection();$q=$pdo->prepare('SELECT * FROM tenant_loyalty_settings WHERE tenant_id=:t');$q->execute(['t'=>$t]);$settings=$q->fetch()?:['enabled'=>0,'points_per_currency'=>1,'reward_points'=>100,'reward_value'=>10,'referral_points'=>50];$q=$pdo->prepare("SELECT c.id,c.name,COALESCE(a.points,0) points FROM customers c LEFT JOIN loyalty_accounts a ON a.customer_id=c.id AND a.tenant_id=c.tenant_id WHERE c.tenant_id=:t AND c.status='active' ORDER BY points DESC,c.name LIMIT 500");$q->execute(['t'=>$t]);$customers=$q->fetchAll();$q=$pdo->prepare("SELECT lr.*,c.name customer_name FROM loyalty_rewards lr JOIN customers c ON c.id=lr.customer_id WHERE lr.tenant_id=:t ORDER BY lr.id DESC LIMIT 100");$q->execute(['t'=>$t]);$rewards=$q->fetchAll();$q=$pdo->prepare("SELECT r.*,a.name referrer_name,b.name referred_name FROM loyalty_referrals r JOIN customers a ON a.id=r.referrer_customer_id JOIN customers b ON b.id=r.referred_customer_id WHERE r.tenant_id=:t ORDER BY r.id DESC LIMIT 100");$q->execute(['t'=>$t]);View::render('loyalty/index',['title'=>'Fidelidade','settings'=>$settings,'customers'=>$customers,'rewards'=>$rewards,'referrals'=>$q->fetchAll()]);}
    public function settings():void{$this->enabled();Authorization::require('loyalty.manage');CSRF::enforce();$t=TenantContext::id();$rate=filter_var(str_replace(',','.',(string)($_POST['points_per_currency']??1)),FILTER_VALIDATE_FLOAT);$rewardPoints=max(1,(int)($_POST['reward_points']??100));$rewardValue=filter_var(str_replace(',','.',(string)($_POST['reward_value']??10)),FILTER_VALIDATE_FLOAT);$referral=max(0,(int)($_POST['referral_points']??50));if($rate===false||$rate<=0||$rewardValue===false||$rewardValue<=0)HttpException::abort(422,'Configuração inválida.');Database::connection()->prepare('INSERT INTO tenant_loyalty_settings(tenant_id,enabled,points_per_currency,reward_points,reward_value,referral_points,updated_at)VALUES(:t,:e,:rate,:rp,:rv,:ref,NOW()) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),points_per_currency=VALUES(points_per_currency),reward_points=VALUES(reward_points),reward_value=VALUES(reward_value),referral_points=VALUES(referral_points),updated_at=NOW()')->execute(['t'=>$t,'e'=>isset($_POST['enabled'])?1:0,'rate'=>$rate,'rp'=>$rewardPoints,'rv'=>$rewardValue,'ref'=>$referral]);Audit::log('loyalty.settings','tenant_loyalty_settings',$t);header('Location: /loyalty');exit;}
    public function adjust():void{$this->enabled();Authorization::require('loyalty.manage');CSRF::enforce();$t=TenantContext::id();$customer=(int)($_POST['customer_id']??0);$points=(int)($_POST['points']??0);$note=trim((string)($_POST['note']??''));if(!$customer||$points===0||strlen($note)<3)HttpException::abort(422,'Ajuste inválido.');$pdo=Database::connection();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT 1 FROM customers WHERE id=:c AND tenant_id=:t AND status='active'");$q->execute(['c'=>$customer,'t'=>$t]);if(!$q->fetchColumn())throw new \DomainException('Cliente inválido.');$q=$pdo->prepare('SELECT points FROM loyalty_accounts WHERE tenant_id=:t AND customer_id=:c FOR UPDATE');$q->execute(['t'=>$t,'c'=>$customer]);$current=(int)($q->fetchColumn()?:0);$new=$current+$points;if($new<0)throw new \DomainException('Saldo insuficiente.');$pdo->prepare('INSERT INTO loyalty_accounts(tenant_id,customer_id,points,updated_at)VALUES(:t,:c,:p,NOW()) ON DUPLICATE KEY UPDATE points=VALUES(points),updated_at=NOW()')->execute(['t'=>$t,'c'=>$customer,'p'=>$new]);$pdo->prepare("INSERT INTO loyalty_transactions(tenant_id,customer_id,type,points,note,user_id,created_at)VALUES(:t,:c,'adjust',:p,:n,:u,NOW())")->execute(['t'=>$t,'c'=>$customer,'p'=>$points,'n'=>$note,'u'=>Auth::user()['id']]);$pdo->commit();Audit::log('loyalty.adjust','customers',$customer,null,['points'=>$points]);}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();HttpException::abort(422,$e->getMessage());}header('Location: /loyalty');exit;}
    public function redeem():void{$this->enabled();Authorization::require('loyalty.manage');CSRF::enforce();$t=TenantContext::id();$customer=(int)($_POST['customer_id']??0);$pdo=Database::connection();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM tenant_loyalty_settings WHERE tenant_id=:t AND enabled=1');$q->execute(['t'=>$t]);$s=$q->fetch();if(!$s)throw new \DomainException('Programa de fidelidade desativado.');$q=$pdo->prepare('SELECT points FROM loyalty_accounts WHERE tenant_id=:t AND customer_id=:c FOR UPDATE');$q->execute(['t'=>$t,'c'=>$customer]);$points=(int)($q->fetchColumn()?:0);$need=(int)$s['reward_points'];if($points<$need)throw new \DomainException('Cliente ainda não possui pontos suficientes.');$pdo->prepare('UPDATE loyalty_accounts SET points=points-:p,updated_at=NOW() WHERE tenant_id=:t AND customer_id=:c')->execute(['p'=>$need,'t'=>$t,'c'=>$customer]);$pdo->prepare("INSERT INTO loyalty_transactions(tenant_id,customer_id,type,points,note,user_id,created_at)VALUES(:t,:c,'redeem',:p,'Resgate de recompensa',:u,NOW())")->execute(['t'=>$t,'c'=>$customer,'p'=>-$need,'u'=>Auth::user()['id']]);$pdo->prepare("INSERT INTO loyalty_rewards(tenant_id,customer_id,points_spent,reward_value,status,issued_at)VALUES(:t,:c,:p,:v,'available',NOW())")->execute(['t'=>$t,'c'=>$customer,'p'=>$need,'v'=>$s['reward_value']]);$reward=(int)$pdo->lastInsertId();$pdo->commit();Audit::log('loyalty.reward.issued','loyalty_rewards',$reward);}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();HttpException::abort(422,$e->getMessage());}header('Location: /loyalty');exit;}
    public function redeemReward(string $id):void{$this->enabled();Authorization::require('loyalty.manage');CSRF::enforce();$t=TenantContext::id();$q=Database::connection()->prepare("UPDATE loyalty_rewards SET status='redeemed',redeemed_at=NOW(),redeemed_by=:u WHERE id=:id AND tenant_id=:t AND status='available'");$q->execute(['u'=>Auth::user()['id'],'id'=>(int)$id,'t'=>$t]);if(!$q->rowCount())HttpException::abort(404,'Recompensa não encontrada ou já utilizada.');Audit::log('loyalty.reward.redeemed','loyalty_rewards',(int)$id);header('Location: /loyalty');exit;}
    public function referral():void{$this->enabled();Authorization::require('loyalty.manage');CSRF::enforce();$t=TenantContext::id();$referrer=(int)($_POST['referrer_customer_id']??0);$referred=(int)($_POST['referred_customer_id']??0);if(!$referrer||!$referred||$referrer===$referred)HttpException::abort(422,'Indicação inválida.');$pdo=Database::connection();$q=$pdo->prepare('SELECT referral_points FROM tenant_loyalty_settings WHERE tenant_id=:t AND enabled=1');$q->execute(['t'=>$t]);$points=$q->fetchColumn();if($points===false)HttpException::abort(422,'Programa de fidelidade desativado.');try{$pdo->prepare("INSERT INTO loyalty_referrals(tenant_id,referrer_customer_id,referred_customer_id,status,reward_points,created_at)VALUES(:t,:a,:b,'pending',:p,NOW())")->execute(['t'=>$t,'a'=>$referrer,'b'=>$referred,'p'=>$points]);}catch(\Throwable){HttpException::abort(422,'Este cliente já possui uma indicação registrada.');}Audit::log('loyalty.referral.created','loyalty_referrals',(int)$pdo->lastInsertId());header('Location: /loyalty');exit;}
}
